  const sectPr = `<w:sectPr><w:pgSz w:w="${wTwips}" w:h="${hTwips}"/><w:pgMar w:top="1020" w:right="1020" w:bottom="1020" w:left="1020" w:header="720" w:footer="720" w:gutter="0"/></w:sectPr>`;
