    colorGroup.appendChild(this.colorApplyBtn);
    const colorDrop = document.createElement('button');
    colorDrop.className = 'mw-toolbar-btn mw-color-drop'; colorDrop.textContent = '▾'; colorDrop.title = '文字颜色';
    colorDrop.addEventListener('pointerdown', e => { e.preventDefault(); e.stopPropagation(); });
    colorDrop.addEventListener('click', e => { e.preventDefault(); e.stopPropagation(); this.colorPaletteAnchorEl = colorDrop; this.toggleColorPalette(); });
    colorGroup.appendChild(colorDrop);
    this.colorPaletteEl = document.createElement('div');
    this.colorPaletteEl.className = 'mw-color-palette is-hidden';
    const palette = ['#202124','#5F6368','#C62828','#E65100','#F9A825','#2E7D32','#00838F','#1565C0','#4527A0','#AD1457'];
    for (const color of palette) {
      const sw = document.createElement('button'); sw.className = 'mw-color-swatch'; sw.style.background = color; sw.title = color;
      sw.addEventListener('pointerdown', e => e.preventDefault());
      sw.addEventListener('click', () => { this.setLastTextColor(color); this.applyTextColor(color); this.toggleColorPalette(false); });
      this.colorPaletteEl.appendChild(sw);
    }
    const custom = document.createElement('input'); custom.type = 'color'; custom.value = this.lastTextColor; custom.title = '自定义颜色';
    custom.addEventListener('input', () => this.setLastTextColor(custom.value));
    custom.addEventListener('change', () => { this.setLastTextColor(custom.value); this.applyTextColor(custom.value); this.toggleColorPalette(false); });
    this.colorPaletteEl.appendChild(custom); colorGroup.appendChild(this.colorPaletteEl);

    formatButton('表格', '插入 3×3 Markdown 表格', () => this.insertTable(3, 3));

    sep();
    button('+ 图片', '把 Vault 中已有图片放到当前页，不复制文件', () => this.chooseImage());
    button('+ 文本框', '在当前页新建可拖动 Markdown 文本框', () => this.addTextBox());
    this.rectToolBtn = button('□ 方框', '拖拽绘制矩形；双击按钮可连续绘制', () => this.toggleDrawMode('rect'));
    this.rectToolBtn.addEventListener('dblclick', e => { e.preventDefault(); this.toggleDrawMode('rect', true); });
    this.arrowToolBtn = button('→ 箭头', '拖拽起点到终点绘制箭头；双击按钮可连续绘制', () => this.toggleDrawMode('arrow'));
    this.arrowToolBtn.addEventListener('dblclick', e => { e.preventDefault(); this.toggleDrawMode('arrow', true); });
    button('粘贴', '粘贴刚复制的图片/文本框/图形到当前页', () => this.pasteObject());
    button('+ 页', '在当前页后新增一页并直接开始输入', () => this.insertPageBreak());
    button('复制全文', '复制当前笔记的 Markdown 到剪贴板', () => this.copyWholeMarkdown());

    const zoomWrap = document.createElement('div');
    zoomWrap.className = 'mw-zoom-controls'; this.toolbarEl.appendChild(zoomWrap);
    this.zoomRangeEl = document.createElement('input'); this.zoomRangeEl.type = 'range'; this.zoomRangeEl.min = '35'; this.zoomRangeEl.max = '250'; this.zoomRangeEl.step = '5'; this.zoomRangeEl.value = String(Math.round((this.viewZoom || 1) * 100)); this.zoomRangeEl.title = '页面显示大小（只改变视角，不改变导出尺寸）';
    this.zoomRangeEl.addEventListener('input', () => this.setZoom(Number(this.zoomRangeEl.value) / 100)); zoomWrap.appendChild(this.zoomRangeEl);
    this.zoomLabelEl = document.createElement('button'); this.zoomLabelEl.className = 'mw-zoom-label'; this.zoomLabelEl.title = '恢复 100%'; this.zoomLabelEl.addEventListener('click', () => this.setZoom(1)); zoomWrap.appendChild(this.zoomLabelEl);
    this.updateZoomLabel();

    const sizeWrap = document.createElement('div'); sizeWrap.className = 'mw-size-controls'; this.toolbarEl.appendChild(sizeWrap);
    const sizeLabel = document.createElement('span'); sizeLabel.textContent = '页面'; sizeWrap.appendChild(sizeLabel);
    this.pagePresetEl = document.createElement('select');
    for (const [key, p] of Object.entries(PAGE_PRESETS)) { const opt = document.createElement('option'); opt.value = key; opt.textContent = p.label; this.pagePresetEl.appendChild(opt); }
    sizeWrap.appendChild(this.pagePresetEl);
    this.pageWidthEl = document.createElement('input'); this.pageWidthEl.type = 'number'; this.pageWidthEl.min = '40'; this.pageWidthEl.max = '1000'; this.pageWidthEl.step = '0.1'; this.pageWidthEl.title = '页面宽度（mm）'; sizeWrap.appendChild(this.pageWidthEl);
    const x = document.createElement('span'); x.textContent = '×'; sizeWrap.appendChild(x);
    this.pageHeightEl = document.createElement('input'); this.pageHeightEl.type = 'number'; this.pageHeightEl.min = '40'; this.pageHeightEl.max = '1000'; this.pageHeightEl.step = '0.1'; this.pageHeightEl.title = '页面高度（mm）'; sizeWrap.appendChild(this.pageHeightEl);
    const mm = document.createElement('span'); mm.textContent = 'mm'; sizeWrap.appendChild(mm);
    const applySize = document.createElement('button'); applySize.textContent = '应用'; applySize.title = '应用页面尺寸并按比例缩放浮动对象'; sizeWrap.appendChild(applySize);
    this.pagePresetEl.addEventListener('change', () => { const p = PAGE_PRESETS[this.pagePresetEl.value]; if (this.pagePresetEl.value !== 'custom') { this.pageWidthEl.value = String(p.widthMm); this.pageHeightEl.value = String(p.heightMm); this.applyPageSize(p.widthMm, p.heightMm, this.pagePresetEl.value); } });
    applySize.addEventListener('click', () => this.applyPageSize(Number(this.pageWidthEl.value), Number(this.pageHeightEl.value), 'custom'));

    // Physical page-size slider: changes width/height in mm together while
