    this.pageStatusEl = document.createElement('span'); this.pageStatusEl.className = 'mw-page-status'; this.pageStatusEl.textContent = 'P1 / 1'; this.toolbarEl.appendChild(this.pageStatusEl);
    this.toolbarEl.appendChild(document.createElement('span')).className = 'mw-toolbar-spacer';
    button('PDF', '打开系统打印对话框，可保存为 PDF', () => this.exportPdf());
    button('PPTX', '导出可编辑文本框、图片和原生图形', () => this.exportPptx());
    button('DOCX', '导出流式 Word 文档', () => this.exportDocx());
    button('MD', '导出 Markdown 副本', () => this.exportMarkdown());
    button('页面', '显示/隐藏页面预览侧栏', () => this.togglePageNavigator());
    button('图层', '显示/隐藏图层面板', () => this.toggleLayers());

    this.workspaceEl = document.createElement('div');
    this.workspaceEl.className = 'mw-workspace'; this.workspaceEl.tabIndex = 0; this.contentEl.appendChild(this.workspaceEl);
    this.workspaceEl.addEventListener('paste', e => this.onWorkspacePaste(e));
