  objectSelectionKey(type,id) { return `${type}:${id}`; }
  frameForObject(type,id) { return type === 'image' ? this.imageFrames.get(id) : type === 'textbox' ? this.textBoxFrames.get(id) : this.shapeFrames.get(id); }
